//SOUND

// ARM SysTick period interrupts
// Input: interrupts every 12.5ns*period
//        priority is 0 (highest) to 3 (lowest)
void Sound_Init(uint32_t period, uint32_t priority){
  // write this
  DAC5_Init();          // Port B is DAC
  Index = 0;
  SysTick->CTRL = 0;         // disable SysTick during setup
  SysTick->LOAD = 40000000/11000-1;  // reload value
  SysTick->VAL = 0;          // any write to current clears it
  SCB->SHP[1] = SCB->SHP[1]&(~0xC0000000)|0x40000000; // set priority = 1
  SysTick->CTRL = 0x0007;    // enable SysTick with core clock and interrupts
}


void Sound_Stop(void){
  // either set LOAD to 0 or clear bit 1 in CTRL
  SysTick->LOAD = 0;
}

const uint8_t* soundpt = 0;
void Sound_Start(const uint8_t* pt, uint32_t period){
    // set reload value
    // write any value to VAL, cause reload
    // write this
    soundpt = pt;
    Index = period-1;
    SysTick->LOAD = 7271;  // reload value
    SysTick->VAL = 0;          // any write to current clears it
    SysTick->CTRL = 0x07;
}

void SysTick_Handler(void){  //ISR for SOUNDS
    // Index = (Index+1)%84524;      // 4,5,6,7,7,7,6,5,4,3,2,1,1,1,2,3,... 
    if(Index)
    {
      Index--;
      soundpt++;
      DAC5_Out(*soundpt);    // output one value each interrupt
    }
    
}

//display start screen
void displayStartScreen(){
  ST7735_SetCursor(0,0); // second row
  ST7735_DrawBitmap(0,160,start_screen,128,127);


  Data = Sensor.In();  // sample 12-bit ADC1 channel 5, PB18, slidepot
  Position = Sensor.Convert(Data);
      
  if (Position > 1000){
    ST7735_OutString((char *)englishTitle);
    ST7735_SetCursor(0,1); // second row
    ST7735_OutString((char *)englishInstruct);
    ST7735_SetCursor(0,2); // third row
    ST7735_OutString((char *)englishInstruct2);
  }
  else{
    ST7735_OutString((char *)spanishTitle);
    ST7735_SetCursor(0,1); // second row
    ST7735_OutString((char *)spanishInstruct);
    ST7735_SetCursor(0,2); // third row
    ST7735_OutString((char *)spanishInstruct2);
  }
  ST7735_DrawBitmap(0, 160, start_screen, 128, 127);
}

//display gold win
void displayGOLD_WIN(){
  __disable_irq();
    DAC5_Init();     // DAC initialization
    Sound_Init(1,0); // SysTick initialization, initially off, priority 0
    __enable_irq();
    
    Sound_Start(fastinvader3, 1054);
    Clock_Delay1ms(500);
    __disable_irq();
  ST7735_SetCursor(0,0);
  ST7735_OutString((char*)goldScoreFinal);
  SmallFont_OutVertical(goldScore, 80, 5);
  ST7735_SetCursor(0,1);
  ST7735_OutString((char*)blueScoreFinal);
  SmallFont_OutVertical(blueScore, 80, 15);
  ST7735_DrawBitmap(0, 91, gold_win, 128, 22);

}

