void Switch_In(){
  if((GPIOA->DIN31_0&(1<<26))>0){
    players[0].vx = -1;
    start = 1;
  }
  if((GPIOA->DIN31_0&(1<<27))>0){
    players[0].vx = 1;
    start = 1;
  }
  if((GPIOA->DIN31_0&(1<<28))>0){
    players[0].jumping = true;
    start = 1;
  } else{
    players[0].jumping = false;
  }

  if((GPIOA->DIN31_0&(1<<15))>0){
    players[1].vx = -1;
    start = 1;
  }
  if((GPIOA->DIN31_0&(1<<17))>0){
    players[1].vx = 1;
    start = 1;
  }
  if((GPIOA->DIN31_0&(1<<18))>0){
    players[1].jumping = true;
    start = 1;
  } else{
    players[1].jumping = false;
  }
  
  if((GPIOB->DIN31_0&(1<<16))>0){
    players[2].vx = -1;
    start = 1;
  }
  if((GPIOB->DIN31_0&(1<<20))>0){
    players[2].vx = 1;
    start = 1;
  }
  if((GPIOB->DIN31_0&(1<<24))>0){
    players[2].jumping = true;
    start = 1;
  } else{
    players[2].jumping = false;
  }
  
  if((GPIOB->DIN31_0&(1<<12))>0){
    players[3].vx = -1;
    start = 1;
  }
  if((GPIOB->DIN31_0&(1<<13))>0){
    players[3].vx = 1;
    start = 1;
  }
  if((GPIOB->DIN31_0&(1<<17))>0){
    players[3].jumping = true;
    start = 1;
  } else{
    players[3].jumping = false;
  }
  
}


